// Turn the AI's JSON reply into the same fields the web form sends.
const msg = $('Telegram Trigger').first().json.message || {};
const chatId = msg.chat ? msg.chat.id : null;

const reply = String($json.text ?? ($json.response && $json.response.text) ?? '');

let data = {};
try {
  const cleaned = reply.replace(/```json|```/gi, '');
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  data = JSON.parse(cleaned.slice(start, end + 1));
} catch (e) {
  data = {};
}

const isClipRequest = data.isClipRequest === true;
delete data.isClipRequest;

// Keep only plain, non-empty values; drop an email that does not look like one
const out = {};
for (const [k, v] of Object.entries(data)) {
  if (v === null || v === undefined || typeof v === 'object') continue;
  const s = String(v).trim();
  if (s) out[k] = s;
}
if (out['Email'] && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(out['Email'])) delete out['Email'];

const what = [out['Language'], out['Keyword (optional)']].filter(Boolean).join(' ');
const ack = isClipRequest
  ? `On it. Looking for ${what ? what + ' ' : ''}videos. If clips can be made, they will be emailed to ${out['Email'] || 'the default address'}. If nothing arrives within an hour, no clips could be made, so try again with different filters.`
  : '';

return { json: { ...out, isClipRequest, ack, telegramChatId: chatId } };

// ✏️ DEFAULTS — used on scheduled runs, and for anything a request leaves blank
const DEFAULTS = {
  email: 'ylguetari@gmail.com',        // where clips go when nobody types an address
  senderEmail: 'ylguetari@gmail.com',  // must be the Gmail account used in the SMTP credential
  region: 'US',
  keyword: 'interview',
  numberOfVideos: 1,
  clipLength: 'Auto',
  language: 'English',
  publishedWithin: 'Last 5 years',
  category: 'Any',
  sortBy: 'Most viewed',
  maxVideoLength: '15 minutes',
  minViews: 'Any',
  aspectRatio: '9:16 Vertical (TikTok, Reels, Shorts)',
  clipsPerVideo: '5',
  clipTopic: '',
};

// This node receives data from FOUR places:
//  - the Clip Desk web page (fields arrive inside "body")
//  - the n8n form (fields arrive at the top level)
//  - the Telegram chat (fields arrive at the top level, plus telegramChatId)
//  - the daily schedule (no fields, so every default above is used)
const raw = $input.first().json;
const input = raw.body || raw;

// Read a field by its exact label, falling back to the default above
function field(label, fallback) {
  const v = input[label];
  return (v === undefined || v === null || v === '') ? fallback : v;
}

const LANGUAGES = { 'English': 'en', 'Spanish': 'es', 'French': 'fr', 'German': 'de', 'Portuguese': 'pt' };
const WINDOWS   = { 'Last 24 hours': 1, 'Last week': 7, 'Last month': 30, 'Last year': 365, 'Last 5 years': 1825 };
const CATEGORIES = { 'Any': '', 'Gaming': '20', 'Comedy': '23', 'Sport': '17', 'News & Politics': '25', 'Education': '27', 'Entertainment': '24', 'People & Blogs': '22' };
const SORTS     = { 'Most viewed': 'viewCount', 'Most recent': 'date', 'Best match': 'relevance' };
const VIEWS     = { 'Any': 0, '100k+': 100000, '1M+': 1000000, '10M+': 10000000 };
const RATIOS    = { '9:16 Vertical (TikTok, Reels, Shorts)': 1, '1:1 Square': 2, '16:9 Horizontal': 4 };
const LENGTHS   = { 'Auto': [0], 'Under 30s': [1], '30-60s': [2], '60-90s': [3] };

const language   = LANGUAGES[field('Language', DEFAULTS.language)] || 'en';
const days       = WINDOWS[field('Published within', DEFAULTS.publishedWithin)] || 1825;
const categoryId = CATEGORIES[field('Category', DEFAULTS.category)] || '';
const order      = SORTS[field('Sort by', DEFAULTS.sortBy)] || 'viewCount';
const minViews   = VIEWS[field('Minimum views', DEFAULTS.minViews)] || 0;
const ratio      = RATIOS[field('Aspect ratio', DEFAULTS.aspectRatio)] || 1;
const preferLength = LENGTHS[field('Clip length', DEFAULTS.clipLength)] || [0];

const maxMinutes    = parseInt(field('Max video length', DEFAULTS.maxVideoLength), 10) || 15;
const clipsPerVideo = Math.min(Math.max(parseInt(field('Clips per video', DEFAULTS.clipsPerVideo), 10) || 5, 1), 10);
const numberOfVideos = Math.min(Math.max(parseInt(field('Number of videos', DEFAULTS.numberOfVideos), 10) || 1, 1), 3);

const keyword   = String(field('Keyword (optional)', DEFAULTS.keyword)).trim();
const clipTopic = String(field('What should the clips be about?', DEFAULTS.clipTopic)).trim();
const region    = field('Region', DEFAULTS.region);

const publishedAfter = new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString().split('.')[0] + 'Z';

// Everything the YouTube Search node sends
const searchParams = {
  part: 'snippet',
  type: 'video',
  order: order,
  videoDuration: 'medium',
  relevanceLanguage: language,
  regionCode: region,
  publishedAfter: publishedAfter,
  maxResults: 50,
};
if (keyword) searchParams.q = keyword;
if (categoryId) searchParams.videoCategoryId = categoryId;

// Everything the Vizard Submit node sends, apart from the per-video bits
const vizardOptions = {
  videoType: 2,
  lang: language,
  preferLength: preferLength,
  ratioOfClip: ratio,
  maxClipNumber: clipsPerVideo,
  subtitleSwitch: 1,
  headlineSwitch: 1,
};
if (clipTopic) vizardOptions.keywords = clipTopic;

let triggeredBy = 'schedule';
if (input.telegramChatId) triggeredBy = 'telegram';
else if (raw.body) triggeredBy = 'page';
else if (input['Email']) triggeredBy = 'form';

return [{
  json: {
    email: field('Email', DEFAULTS.email),
    senderEmail: DEFAULTS.senderEmail,
    language: language,
    region: region,
    keyword: keyword,
    numberOfVideos: numberOfVideos,
    maxVideoMinutes: maxMinutes,
    minViews: minViews,
    publishedAfter: publishedAfter,
    searchParams: searchParams,
    vizardOptions: vizardOptions,
    triggeredBy: triggeredBy,
  },
}];

// Keep only videos that can actually be clipped and have not been clipped before,
// then take the most viewed ones.
const settings = $('Settings').first().json;
const items = $('YouTube Video Stats').first().json.items || [];
const lang = settings.language || 'en';
const maxMinutes = settings.maxVideoMinutes || 20;
const minViews = settings.minViews || 0;

// Video IDs already stored in the clipped_videos data table (empty table = empty set)
const alreadyDone = new Set(
  $('Get Past Videos').all().map(i => i.json.videoId).filter(Boolean)
);

// YouTube returns durations like PT12M34S — turn that into minutes
function minutes(iso) {
  const m = /^PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/.exec(iso || '');
  if (!m) return 99999; // unparseable: treat as too long, to protect credits
  return Number(m[1] || 0) * 60 + Number(m[2] || 0) + Number(m[3] || 0) / 60;
}

const videos = items
  .filter(v => !alreadyDone.has(v.id))
  .filter(v => v.snippet.liveBroadcastContent === 'none')
  .filter(v => v.snippet.categoryId !== '10')
  .filter(v => {
    const audio = v.snippet.defaultAudioLanguage || v.snippet.defaultLanguage || '';
    return audio.toLowerCase().startsWith(lang);
  })
  .filter(v => minutes(v.contentDetails.duration) <= maxMinutes)
  .filter(v => Number(v.statistics.viewCount || 0) >= minViews)
  .map(v => ({
    videoId: v.id,
    title: v.snippet.title,
    channel: v.snippet.channelTitle,
    views: Number(v.statistics.viewCount || 0),
    lengthMinutes: Math.round(minutes(v.contentDetails.duration) * 10) / 10,
    url: 'https://www.youtube.com/watch?v=' + v.id,
    vizardOptions: settings.vizardOptions,
    requestedBy: settings.triggeredBy,
  }))
  .sort((a, b) => b.views - a.views)
  .slice(0, settings.numberOfVideos);

if (videos.length === 0) {
  throw new Error('Nothing new matched. Try a wider time window, a lower minimum view count, or a longer max length. (Videos already clipped before are skipped.)');
}

return videos.map(v => ({ json: v }));

// One flat row for the clipped_videos data table (no arrays allowed in a row)
const v = $json;
const clips = Array.isArray(v.clips) ? v.clips : [];
return {
  json: {
    videoId: v.videoId || '',
    title: String(v.title || '').slice(0, 200),
    channel: String(v.channel || ''),
    views: Number(v.views || 0),
    status: clips.length ? 'ok' : (v.status && v.status !== 'ok' ? String(v.status) : 'no clips'),
    clipCount: clips.length,
    requestedBy: String(v.requestedBy || ''),
  },
};

// Build one HTML email from the videos that actually produced clips.
// If no video produced a clip, return nothing so no email is sent.
const settings = $('Settings').first().json;
const videos = $input.all()
  .map(i => i.json)
  .filter(v => v.clips && v.clips.length > 0);

if (videos.length === 0) {
  return [];
}

const esc = s => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const date = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
const totalClips = videos.reduce((n, v) => n + v.clips.length, 0);

let html = `<div style="font-family:Arial,sans-serif;max-width:640px;color:#222">`;
html += `<h2>🎬 Your clips – ${date}</h2>`;
html += `<p>${totalClips} clip(s) generated from ${videos.length} video(s).</p>`;

for (const v of videos) {
  html += `<hr><h3 style="margin-bottom:4px">${esc(v.title)}</h3>`;
  html += `<p style="margin-top:0;color:#666">${esc(v.channel)} · ${Number(v.views || 0).toLocaleString('en-US')} views`;
  if (v.url) html += ` · <a href="${esc(v.url)}">original video</a>`;
  html += `</p><ol>`;
  for (const c of v.clips) {
    html += `<li style="margin-bottom:10px"><b>${esc(c.title)}</b><br>`;
    html += `Viral score ${esc(c.viralScore)}/10 · ${c.seconds}s<br>`;
    html += `<a href="${esc(c.url)}">⬇️ Download</a> · <a href="${esc(c.editorUrl)}">✏️ Edit in Vizard</a></li>`;
  }
  html += `</ol>`;
}

html += `<p style="color:#999;font-size:12px">Download links expire after 7 days. Review each clip before posting it.</p></div>`;

return [{
  json: {
    to: settings.email,
    subject: `🎬 ${totalClips} new clip(s) ready – ${date}`,
    html,
  },
}];
